sys_script_fix.script:
var reqClose = new GlideRecord('sc_request');
reqClose.addQuery('request_state', '!=', 'closed_complete');
//Update as needed
reqClose.setLimit(10);
reqClose.setWorkflow(false);
reqClose.query();

while (reqClose.next()) {
    var ritmQuery = new GlideRecord('sc_req_item');
    ritmQuery.addQuery('request', reqClose.getValue('sys_id'));
    ritmQuery.addQuery('state', '3');
    ritmQuery.addOrQuery('state', '4');
    ritmQuery.addOrQuery('state', '7');
    ritmQuery.query();

    //-----Should also turn off notifications for the instance (or at least the ones for REQ)

    if (!ritmQuery.next()) {

        reqClose.stage = "closed_complete";
        reqClose.request_state = "closed_complete";
        reqClose.update();

    }
}
